উত্তর: 
#include <stdio.h>

int main() {
    int num;

    // ইউজারের থেকে সংখ্যা নেওয়া
    printf("Enter an integer: ");
    scanf("%d", &num);

    // শর্ত চেক করা
    if(num % 2 == 0) {
        printf("%d is an Even number.\n", num);
    } else {
        printf("%d is an Odd number.\n", num);
    }

    return 0;
}

যুক্তি (Logic): কোনো সংখ্যাকে ২ দিয়ে ভাগ করলে যদি ভাগশেষ ০ হয় (অর্থাৎ num % 2 == 0), তবে সংখ্যাটি জোড়। আর ভাগশেষ ০ না হলে সেটি বিজোড়। % (মডuলাস) অপারেটর ভাগশেষ বের করতে সাহায্য করে।

উত্তর: 
#include <stdio.h>

int main() {
    int a, b, c;

    printf("Enter three numbers: ");
    scanf("%d %d %d", &a, &b, &c);

    if(a >= b && a >= c) {
        printf("%d is the largest number.", a);
    } else if(b >= a && b >= c) {
        printf("%d is the largest number.", b);
    } else {
        printf("%d is the largest number.", c);
    }

    return 0;
}

যুক্তি (Logic):  এখানে লজিক্যাল অ্যান্ড && ব্যবহার করে চেক করা হয়েছে। যদি a, b এবং c উভয়ের চেয়েই বড় হয়, তবে a বড়। তা না হলে যদি b, a এবং c উভয়ের চেয়ে বড় হয়, তবে b বড়। অন্যথায় c বড় হবে।

উত্তর: for লুপ হলো এমন একটি পদ্ধতি, যার মাধ্যমে একটি নির্দিষ্ট শর্ত পূরণ না হওয়া পর্যন্ত কোনো কাজ বা কোড নির্দিষ্ট সংখ্যক বার বারবার চালানো যায়।

সিনট্যাক্স (Syntax):
for (initialization; condition; increment/decrement) {
    // কোড যা বারবার রান হবে
}

১ থেকে ১০ পর্যন্ত প্রিন্ট করার প্রোগ্রাম:
#include <stdio.h>

int main() {
    int i;

    // i এর মান 1 থেকে শুরু হবে, 10 পর্যন্ত চলবে এবং প্রতিবার 1 করে বাড়বে
    for(i = 1; i <= 10; i++) {
        printf("%d ", i);
    }

    return 0;
}

যুক্তি (Logic): প্রথমে i = 1 সেট করা হয়। এরপর শর্ত i <= 10 চেক হয়। সত্য হলে ভেতরের printf কাজ করে। তারপর i++ এর ফলে i এর মান বেড়ে ২ হয়। এভাবেই ১০ পর্যন্ত লুপটি চলতে থাকে।

উত্তর: 
#include <stdio.h>

int main() {
    int num;

    // ইউজারের কাছ থেকে ইনপুট নেওয়া
    printf("Enter any number: ");
    scanf("%d", &num);

    // শর্ত চেক করা (২ দিয়ে ভাগ করলে ভাগশেষ ০ হয় কি না)
    if(num % 2 == 0) {
        printf("The number is Even.\n");
    } else {
        printf("The number is Odd.\n");
    }

    return 0;
}

প্র্যাকটিক্যাল রান করার ধাপ:

১. Turbo C বা Dev C++ ওপেন করে কোডটি লিখতে হবে।
২. ফাইলটি evenodd.c নামে সেভ করতে হবে।
৩. কোডটি Compile করতে হবে (Turbo C তে Alt+F9)।
৪. এরপর রান করতে হবে (Ctrl+F9)। স্ক্রিনে নম্বর চাইলে নম্বর দিয়ে এন্টার দিলেই উত্তর দেখাবে।
